<script>
document.addEventListener('DOMContentLoaded',function(){const cards=[...document.querySelectorAll('.cs-card')],groups=[...document.querySelectorAll('.cs-group')],filters=[...document.querySelectorAll('.cs-filter')],input=document.getElementById('cs-service-search'),count=document.getElementById('cs-count');function apply(){const q=(input.value||'').trim().toLowerCase(),active=document.querySelector('.cs-filter.active')?.dataset.filter||'all';let n=0;cards.forEach(c=>{const cat=c.closest('.cs-group').dataset.category,okCat=active==='all'||cat===active,okQ=!q||(c.dataset.service||'').includes(q);c.style.display=okCat&&okQ?'flex':'none';if(okCat&&okQ)n++});groups.forEach(g=>{const visible=[...g.querySelectorAll('.cs-card')].some(c=>c.style.display!=='none');g.style.display=visible?'block':'none'});count.textContent=n}filters.forEach(f=>f.addEventListener('click',function(){filters.forEach(x=>x.classList.remove('active'));this.classList.add('active');apply()});input.addEventListener('input',apply);document.getElementById('cs-search-btn').addEventListener('click',apply)});
</script>
